INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1026, '数学', '三年级', 'apply', 3, '{"stem": "思维拓展：推算数字。◎+◎+◎+◎+◎+◎+◎=84，□+□×◎=52。◎=（ ），□=（ ）。（10分）"}', '◎=12, □=4', '7×◎=84→◎=12; □+12×□=52→13×□=52→□=4', 'jsj3_sx_v109', '["jsj3_sx","U4","p067","think_01"]', 1, NULL);